use std::path::{Path, PathBuf};

use serde::Deserialize;

/// `/etc/tulsi/tulsid.json`, generated by the `tulsi.daemon` NixOS module.
#[derive(Debug, Clone, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct Config {
    /// Git-tracked directory of the system flake, e.g. `/etc/nixos`.
    pub flake_dir: PathBuf,
    /// Command run after state.json changed, e.g.
    /// `["nixos-rebuild", "switch", "--flake", "/etc/nixos#host"]`.
    pub rebuild_command: Vec<String>,
    /// Copied to `<flakeDir>/tulsi/state.json` if that file does not exist.
    #[serde(default)]
    pub initial_state: Option<PathBuf>,
    /// Check polkit authorization for changes. Only disable for development
    /// on a session bus.
    #[serde(default = "yes")]
    pub polkit: bool,
    /// Package search index; enables Search and early rejection of unknown names.
    #[serde(default)]
    pub package_index: Option<PathBuf>,
    /// Which programs come from which packages (`program<TAB>attr`, see
    /// nix/packages/program-index.nix); lets `Match` find packages by program.
    #[serde(default)]
    pub program_index: Option<PathBuf>,
    /// Mirrors `nixpkgs.config.allowUnfree`; unfree packages are refused otherwise.
    #[serde(default)]
    pub allow_unfree: bool,
    /// Unfree packages (AI agent CLIs) that may be installed once a person accepts
    /// their licence, with that licence: attr → { name, url }.
    #[serde(default)]
    pub unfree_agents: std::collections::BTreeMap<String, tulsi_client::License>,
    /// The rebuild command for changes that take effect at the next start
    /// (ADR 0029); empty: `rebuildCommand` with `switch` replaced by `boot`.
    #[serde(default)]
    pub boot_rebuild_command: Vec<String>,
    /// "systemd-boot", "grub" or "" (none or unknown): how a change on trial
    /// is started only once.
    #[serde(default)]
    pub boot_loader: String,
    /// The system profile, whose generations the boot entries are.
    #[serde(default = "system_profile")]
    pub system_profile: PathBuf,
    /// The system this boot started with.
    #[serde(default = "booted_system")]
    pub booted_system: PathBuf,
    /// Where a change on trial is recorded.
    #[serde(default = "crate::trial::default_trial_file")]
    pub trial_file: PathBuf,
    /// With GRUB, how long after starting a change on trial is undone unless kept.
    #[serde(default = "trial_timeout")]
    pub trial_timeout_secs: u64,
}

fn system_profile() -> PathBuf {
    PathBuf::from("/nix/var/nix/profiles/system")
}

fn booted_system() -> PathBuf {
    PathBuf::from("/run/booted-system")
}

fn trial_timeout() -> u64 {
    600
}

fn yes() -> bool {
    true
}

impl Config {
    pub fn load(path: &Path) -> Result<Self, String> {
        let text = std::fs::read_to_string(path)
            .map_err(|e| format!("cannot read config {}: {e}", path.display()))?;
        let cfg: Config = serde_json::from_str(&text)
            .map_err(|e| format!("invalid config {}: {e}", path.display()))?;
        if cfg.rebuild_command.is_empty() {
            return Err("rebuildCommand must not be empty".into());
        }
        Ok(cfg)
    }

    /// Path of the state file relative to `flake_dir` (used with git).
    pub const STATE_REL: &'static str = "tulsi/state.json";
    /// The user's own NixOS settings, editable through ApplyConfig.
    pub const CONFIG_REL: &'static str = "configuration.nix";
    /// Packages made on this machine: `<PKGS_REL>/<name>/package.nix` (+ meta.json).
    pub const PKGS_REL: &'static str = "tulsi/pkgs";
    /// Pins the TulsiOS release (the `tulsi` input) and everything it pins;
    /// `Upgrade` moves it (ADR 0017).
    pub const LOCK_REL: &'static str = "flake.lock";

    pub fn state_path(&self) -> PathBuf {
        self.flake_dir.join(Self::STATE_REL)
    }
}
